/// Java small-shape heuristics per node type (positive size within the
/// type's icon ceiling).
bool _smallShapeByType(String type, double width, double height) {
  final ceiling = switch (type) {
    'COMPONENT' || 'INSTANCE' => 48.0,
    'VECTOR' => 64.0,
    'RECTANGLE' || 'ELLIPSE' => 50.0,
    _ => 0.0,
  };
  return ceiling > 0 &&
      width > 0 &&
      height > 0 &&
      width <= ceiling &&
      height <= ceiling;
}

