    });

    test('multi-line <code> restores as a {code:java} block', () {
      const html = '<code>line1\nline2</code>';
      expect(markdownToJiraMarkup(html), '{code:java}line1\nline2{code}');
    });

    test('<pre><code> keeps an explicit language class', () {

